{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-2AOsdg/src/address.js","content":"// Address parsing and utilities: columns A-Z, AA-ZZ; rows 1-999 (1-3 digits).

export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 65
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 65)
}

export function indexToCol(idx) {
  if (idx < 26) return String.fromCharCode(65 + idx)
  idx -= 26
  const a = Math.floor(idx / 26)
  const b = idx % 26
  return String.fromCharCode(65 + a) + String.fromCharCode(65 + b)
}

// Parses a raw token (as read from a line or a formula word) into a
// canonical address, or { ok: false } if it is not a valid addressable
// cell (wrong shape, too many letters/digits, or row < 1).
export function analyzeAddress(str) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(str)
  if (!m) return { ok: false }
  const letters = m[1].toUpperCase()
  const digits = m[2]
  if (letters.length < 1 || letters.length > 2) return { ok: false }
  if (digits.length < 1 || digits.length > 3) return { ok: false }
  const row = parseInt(digits, 10)
  if (row < 1) return { ok: false }
  const ci = colIndex(letters)
  return { ok: true, col: letters, row, key: letters + row, colIndex: ci }
}

// Expands a range between two (already-valid) address infos into the list
// of covered cells, in ascending column then ascending row order.
export function expandRange(a, b) {
  const cmin = Math.min(a.colIndex, b.colIndex)
  const cmax = Math.max(a.colIndex, b.colIndex)
  const rmin = Math.min(a.row, b.row)
  const rmax = Math.max(a.row, b.row)
  const out = []
  for (let c = cmin; c <= cmax; c++) {
    const col = indexToCol(c)
    for (let r = rmin; r <= rmax; r++) {
      out.push({ col, row: r, key: col + r, colIndex: c })
    }
  }
  return out
}
"}

