{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-2AOsdg/src/lexer.js","content":"// Tokenizer for a formula body (the part of the content after the leading '=').

function isDigit(c) { return c >= '0' && c <= '9' }
function isAlpha(c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') }

export class LexError extends Error {}

export function tokenize(s) {
  const toks = []
  const n = s.length
  let i = 0
  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    if (isDigit(c)) {
      let j = i + 1
      while (j < n && isDigit(s[j])) j++
      if (s[j] === '.' && j + 1 < n && isDigit(s[j + 1])) {
        let k = j + 1
        while (k < n && isDigit(s[k])) k++
        toks.push({ t: 'num', v: s.slice(i, k) })
        i = k
        continue
      }
      toks.push({ t: 'num', v: s.slice(i, j) })
      i = j
      continue
    }
    if (isAlpha(c)) {
      let j = i + 1
      while (j < n && isAlpha(s[j])) j++
      let k = j
      while (k < n && isDigit(s[k])) k++
      toks.push({ t: 'word', v: s.slice(i, k) })
      i = k
      continue
    }
    const two = s.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      toks.push({ t: 'op', v: two })
      i += 2
      continue
    }
    if ('<>=+-*/^'.includes(c)) {
      toks.push({ t: 'op', v: c })
      i++
      continue
    }
    if (c === '(') { toks.push({ t: 'lparen' }); i++; continue }
    if (c === ')') { toks.push({ t: 'rparen' }); i++; continue }
    if (c === ',') { toks.push({ t: 'comma' }); i++; continue }
    if (c === ':') { toks.push({ t: 'colon' }); i++; continue }
    throw new LexError(`unexpected character ${c}`)
  }
  toks.push({ t: 'eof' })
  return toks
}
"}

