{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-2AOsdg/src/parser.js","content":"// Recursive-descent parser for a formula body.
//
// Precedence, loosest first: comparisons, +/-, then * /, then ^, then a
// leading unary +/-. Comparisons, +/- and * / group to the left; ^ groups
// to the right; a leading sign binds tighter than ^.
//
// A range (word ':' word) is only accepted directly as a function argument.

export class ParseError extends Error {}

const CMP_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() { return this.tokens[this.pos] }
  next() { return this.tokens[this.pos++] }

  expect(type) {
    const tok = this.next()
    if (tok.t !== type) throw new ParseError(`expected ${type}`)
    return tok
  }

  parseFormula() {
    const node = this.parseExpr()
    if (this.peek().t !== 'eof') throw new ParseError('trailing tokens')
    return node
  }

  parseExpr() { return this.parseComparison() }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek().t === 'op' && CMP_OPS.has(this.peek().v)) {
      const op = this.next().v
      const right = this.parseAdditive()
      left = { kind: 'binop', op, left, right, cmp: true }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek().t === 'op' && (this.peek().v === '+' || this.peek().v === '-')) {
      const op = this.next().v
      const right = this.parseMultiplicative()
      left = { kind: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek().t === 'op' && (this.peek().v === '*' || this.peek().v === '/')) {
      const op = this.next().v
      const right = this.parsePower()
      left = { kind: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek().t === 'op' && this.peek().v === '^') {
      this.next()
      const right = this.parsePower()
      return { kind: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek().t === 'op' && (this.peek().v === '+' || this.peek().v === '-')) {
      const op = this.next().v
      const node = this.parseUnary()
      return { kind: 'unary', op, node }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.peek()
    if (tok.t === 'num') {
      this.next()
      return { kind: 'num', value: parseFloat(tok.v) }
    }
    if (tok.t === 'lparen') {
      this.next()
      const e = this.parseExpr()
      this.expect('rparen')
      return e
    }
    if (tok.t === 'word') {
      this.next()
      if (this.peek().t === 'lparen') {
        this.next()
        const args = []
        if (this.peek().t !== 'rparen') {
          args.push(this.parseArgument())
          while (this.peek().t === 'comma') {
            this.next()
            args.push(this.parseArgument())
          }
        }
        this.expect('rparen')
        return { kind: 'call', name: tok.v.toUpperCase(), args }
      }
      const upper = tok.v.toUpperCase()
      if (upper === 'TRUE') return { kind: 'bool', value: true }
      if (upper === 'FALSE') return { kind: 'bool', value: false }
      return { kind: 'cell', word: tok.v }
    }
    throw new ParseError('unexpected token')
  }

  parseArgument() {
    const t = this.tokens
    const p = this.pos
    if (t[p] && t[p].t === 'word' && t[p + 1] && t[p + 1].t === 'colon' && t[p + 2] && t[p + 2].t === 'word') {
      const word1 = t[p].v
      const word2 = t[p + 2].v
      this.pos = p + 3
      return { kind: 'range', word1, word2 }
    }
    return this.parseExpr()
  }
}

export function parseFormula(tokens) {
  return new Parser(tokens).parseFormula()
}
"}

