export const NUM = (v) => ({ t: 'num', v })
export const TXT = (v) => ({ t: 'txt', v })
export const BOOL = (v) => ({ t: 'bool', v })
export const ERR = (v) => ({ t: 'err', v })

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

// Reads a value as a number for an arithmetic position.
export function toNumber(val) {
  if (val.t === 'err') return val
  if (val.t === 'num') return val
  if (val.t === 'bool') return NUM(val.v ? 1 : 0)
  return ERR('#VALUE!')
}

// Reads a value as a condition (for IF).
export function toCondition(val) {
  if (val.t === 'err') return val
  if (val.t === 'bool') return val
  if (val.t === 'num') return BOOL(val.v !== 0)
  return ERR('#VALUE!')
}

// Compares two non-error values. Numbers < text < booleans across kinds;
// within a kind: numeric, code-point, and false-below-true respectively.
export function compare(a, b) {
  const rank = (v) => (v.t === 'num' ? 0 : v.t === 'txt' ? 1 : 2)
  if (a.t !== b.t) return rank(a) - rank(b)
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'txt') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.v === b.v) return 0
  return a.v ? 1 : -1
}
"}

