import { tokenize, LexError } from './lexer.js'
import { parseFormula, ParseError } from './parser.js'
import { NUM, TXT, ERR, ERROR_TOKENS } from './values.js'

export class CliError extends Error {}

const LITERAL_NUMBER_RE = /^-?\d+(\.\d+)?$/

function classifyContent(content) {
  if (content.startsWith('=')) {
    const src = content.slice(1)
    try {
      const tokens = tokenize(src)
      const ast = parseFormula(tokens)
      return { isFormula: true, ast, parseError: false }
    } catch (e) {
      if (e instanceof LexError || e instanceof ParseError) {
        return { isFormula: true, ast: null, parseError: true }
      }
      throw e
    }
  }
  if (content === '') return { isFormula: false, literalValue: NUM(0) }
  if (LITERAL_NUMBER_RE.test(content)) return { isFormula: false, literalValue: NUM(parseFloat(content)) }
  if (ERROR_TOKENS.includes(content)) return { isFormula: false, literalValue: ERR(content) }
  return { isFormula: false, literalValue: TXT(content) }
}

// Parses the whole sheet text into a Map from canonical address key to cell
// entry. Throws CliError (with a message ready to prefix with "error: ") on
// a line-level failure.
export function parseSheetText(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    const stripped = line.slice(j)
    if (stripped.length === 0) continue
    if (stripped[0] === '#') continue

    let k = 0
    while (k < stripped.length && stripped[k] !== ' ' && stripped[k] !== '\t') k++
    const addrRaw = stripped.slice(0, k)
    const rest = stripped.slice(k)
    let m = 0
    while (m < rest.length && (rest[m] === ' ' || rest[m] === '\t')) m++
    const content = rest.slice(m)

    const info = analyzeAddress(addrRaw)
    if (!info.ok) {
      throw new CliError(`line ${lineNo}: invalid cell address ${addrRaw.toUpperCase()}`)
    }
    if (cells.has(info.key)) {
      throw new CliError(`line ${lineNo}: cell ${info.key} is declared twice`)
    }
    const classified = classifyContent(content)
    cells.set(info.key, { col: info.col, row: info.row, colIndex: info.colIndex, content, ...classified })
  }
  return cells
}
"}

