// Walks a parsed formula AST, collecting every distinct addressable cell it
// names directly (ranges expanded). Returns a Map from key to address info.
export function collectDeps(ast) {
  const out = new Map()

  function add(info) { out.set(info.key, info) }

  function visit(node) {
    if (!node) return
    switch (node.kind) {
      case 'num':
      case 'bool':
        return
      case 'cell': {
        const info = analyzeAddress(node.word)
        if (info.ok) add(info)
        return
      }
      case 'range': {
        const a = analyzeAddress(node.word1)
        const b = analyzeAddress(node.word2)
        if (a.ok && b.ok) {
          for (const cell of expandRange(a, b)) add(cell)
        }
        return
      }
      case 'unary':
        visit(node.node)
        return
      case 'binop':
        visit(node.left)
        visit(node.right)
        return
      case 'call':
        for (const arg of node.args) visit(arg)
        return
      default:
        return
    }
  }

  visit(ast)
  return out
}
"}

