import { NUM, BOOL, ERR, toNumber, toCondition, compare } from './values.js'

const KNOWN_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

// Builds an evaluator bound to a sheet (Map key -> cell entry). Cell values
// are computed lazily and memoized; self-reaching cells report #CYCLE!.
export function makeEvaluator(sheet) {
  const cache = new Map()
  const visiting = new Set()

  function getCellValue(key) {
    if (cache.has(key)) return cache.get(key)
    const entry = sheet.get(key)
    if (!entry) {
      const v = NUM(0)
      cache.set(key, v)
      return v
    }
    if (visiting.has(key)) return ERR('#CYCLE!')
    if (!entry.isFormula) {
      cache.set(key, entry.literalValue)
      return entry.literalValue
    }
    if (entry.parseError) {
      const v = ERR('#ERR!')
      cache.set(key, v)
      return v
    }
    visiting.add(key)
    const v = evalNode(entry.ast)
    visiting.delete(key)
    cache.set(key, v)
    return v
  }

  function resolveWord(word) {
    const info = analyzeAddress(word)
    if (!info.ok) return ERR('#REF!')
    return getCellValue(info.key)
  }

  function expandRangeValues(word1, word2) {
    const a = analyzeAddress(word1)
    const b = analyzeAddress(word2)
    if (!a.ok || !b.ok) return [ERR('#REF!')]
    return expandRange(a, b).map((c) => getCellValue(c.key))
  }

  function flattenArg(node) {
    if (node.kind === 'range') return expandRangeValues(node.word1, node.word2)
    return [evalNode(node)]
  }

  // Evaluates an argument expected to yield a single value; a range in this
  // position contributes its first error, or else its first cell's value.
  function evalArgSingle(node) {
    if (node.kind === 'range') {
      const vals = expandRangeValues(node.word1, node.word2)
      const e = vals.find((v) => v.t === 'err')
      if (e) return e
      return vals.length ? vals[0] : ERR('#ERR!')
    }
    return evalNode(node)
  }

  function evalNode(node) {
    switch (node.kind) {
      case 'num':
        return NUM(node.value)
      case 'bool':
        return BOOL(node.value)
      case 'cell':
        return resolveWord(node.word)
      case 'range':
        return evalArgSingle(node)
      case 'unary': {
        const v = evalNode(node.node)
        const n = toNumber(v)
        if (n.t === 'err') return n
        const r = node.op === '-' ? -n.v : +n.v
        if (!Number.isFinite(r)) return ERR('#DIV/0!')
        return NUM(r)
      }
      case 'binop':
        return evalBinop(node)
      case 'call':
        return evalCall(node)
      default:
        return ERR('#ERR!')
    }
  }

  function evalBinop(node) {
    const l = evalNode(node.left)
    const r = evalNode(node.right)
    if (node.cmp) {
      if (l.t === 'err') return l
      if (r.t === 'err') return r
      const c = compare(l, r)
      switch (node.op) {
        case '=': return BOOL(c === 0)
        case '<>': return BOOL(c !== 0)
        case '<': return BOOL(c < 0)
        case '<=': return BOOL(c <= 0)
        case '>': return BOOL(c > 0)
        case '>=': return BOOL(c >= 0)
      }
    }
    const ln = toNumber(l)
    if (ln.t === 'err') return ln
    const rn = toNumber(r)
    if (rn.t === 'err') return rn
    let res
    switch (node.op) {
      case '+': res = ln.v + rn.v; break
      case '-': res = ln.v - rn.v; break
      case '*': res = ln.v * rn.v; break
      case '/':
        if (rn.v === 0) return ERR('#DIV/0!')
        res = ln.v / rn.v
        break
      case '^': res = Math.pow(ln.v, rn.v); break
    }
    if (!Number.isFinite(res)) return ERR('#DIV/0!')
    return NUM(res)
  }

  function evalCall(node) {
    const name = node.name
    const args = node.args
    if (!KNOWN_FUNCTIONS.has(name)) return ERR('#NAME?')

    if (name === 'IF') {
      if (args.length !== 3) return ERR('#ERR!')
      const cond = toCondition(evalArgSingle(args[0]))
      if (cond.t === 'err') return cond
      return cond.v ? evalArgSingle(args[1]) : evalArgSingle(args[2])
    }

    if (name === 'ABS') {
      if (args.length !== 1) return ERR('#ERR!')
      const n = toNumber(evalArgSingle(args[0]))
      if (n.t === 'err') return n
      const r = Math.abs(n.v)
      if (!Number.isFinite(r)) return ERR('#DIV/0!')
      return NUM(r)
    }

    // SUM, MIN, MAX, COUNT, AVG
    if (args.length < 1) return ERR('#ERR!')
    const flat = []
    for (const a of args) flat.push(...flattenArg(a))
    const firstErr = flat.find((v) => v.t === 'err')
    if (firstErr) return firstErr

    if (name === 'COUNT') return NUM(flat.filter((v) => v.t === 'num').length)

    const nums = []
    for (const v of flat) {
      const n = toNumber(v)
      if (n.t === 'err') return n
      nums.push(n.v)
    }
    let result
    if (name === 'SUM') result = nums.reduce((a, b) => a + b, 0)
    else if (name === 'MIN') result = Math.min(...nums)
    else if (name === 'MAX') result = Math.max(...nums)
    else if (name === 'AVG') result = nums.reduce((a, b) => a + b, 0) / nums.length
    if (!Number.isFinite(result)) return ERR('#DIV/0!')
    return NUM(result)
  }

  return { getCellValue }
}
