/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheetText, CliError } from './sheet.js'
import { makeEvaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatNumber } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatValue(v) {
  if (v.t === 'num') return formatNumber(v.v)
  if (v.t === 'err') return v.v
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let sheet
  try {
    sheet = parseSheetText(input)
  } catch (e) {
    if (e instanceof CliError) {
      fail(e.message)
      return
    }
    throw e
